import React from 'react';
import { AbsoluteFill, interpolate, useCurrentFrame } from 'remotion';
import { COLORS, EASINGS } from '../../brand';
import { FONT_BODY, FONT_MONO } from '../../fonts';
import { CLAMP } from '../../lib/kit';
import { CaptionTrack, CoverImage, HookTitle, ProgressBar, SAFE, ShortBg, ToolCard, Watermark, secToFrame } from '../../lib/shorts';
import { WORDS } from './words';

// short-113: generated by the daily batch. Cover held at frame 0; closes on the cover.
export const compositionConfig = { id: 'Short113', durationInSeconds: 40.0, fps: 30, width: 1080, height: 1920 };

const CTA = secToFrame(36.0);
const B0 = secToFrame(3.7);
const B1 = secToFrame(11.0);
const B2 = secToFrame(13.7);
const B3 = secToFrame(17.6);
const B4 = secToFrame(21.6);
const B5 = secToFrame(23.5);
const B6 = secToFrame(27.8);

const FadeOut: React.FC<{ at: number; children: React.ReactNode }> = ({ at, children }) => {
  const frame = useCurrentFrame();
  const op = 1 - interpolate(frame, [at - 8, at + 2], [0, 1], { ...CLAMP, easing: EASINGS.easeIn });
  return <AbsoluteFill style={{ opacity: op }}>{children}</AbsoluteFill>;
};

const Line: React.FC<{ k: string; v: string; good?: boolean; bad?: boolean }> = ({ k, v, good, bad }) => (
  <div style={{ display: 'flex', justifyContent: 'space-between', fontFamily: FONT_MONO, fontSize: 32 }}>
    <span style={{ color: COLORS.d400 }}>{k}</span>
    <span style={{ color: bad ? COLORS.danger : good ? COLORS.signalAlt : COLORS.d300, fontWeight: good || bad ? 700 : 400 }}>{v}</span>
  </div>
);
const Panel: React.FC<{ children: React.ReactNode }> = ({ children }) => (
  <div style={{ background: COLORS.d900, borderRadius: 12, padding: '24px 26px', display: 'flex', flexDirection: 'column', gap: 16 }}>{children}</div>
);

const Short113: React.FC = () => {
  const frame = useCurrentFrame();
  const ctaOp = interpolate(frame, [CTA, CTA + 12], [0, 1], { ...CLAMP, easing: EASINGS.easeOut });
  return (
    <AbsoluteFill>
      <ShortBg />
      <FadeOut at={B0}>
        <CoverImage src="projects/short-113/cover.png" out={B0 - 10} />
        <HookTitle hold onDark kicker="GEMINI VOICE PRICING" lines={[{ text: "TTS $9 NOW" },{ text: "$18 JAN 1", accent: true }]} />
      </FadeOut>
      <FadeOut at={B1}>
        <ToolCard name="Gemini 3.8 Flash TTS" tagline="Audio out, right now." chip="$9 / 1M" at={B0 - 2}>
          <Panel>
            <Line k="audio out /1M" v="$9.00" good />
            <Line k="text in /1M" v="$0.50" good />
          </Panel>
        </ToolCard>
      </FadeOut>
      <FadeOut at={B2}>
        <ToolCard name="From January 1" tagline="Audio out doubles." chip="$18 / 1M" at={B1 - 2} chipColor={COLORS.danger}>
          <Panel>
            <Line k="audio out /1M" v="$9 to $18" bad />
            <Line k="starts" v="Jan 1, 2027" />
          </Panel>
        </ToolCard>
      </FadeOut>
      <FadeOut at={B3}>
        <ToolCard name="Flash-Lite TTS" tagline="Doubles too." chip="$6 to $12" at={B2 - 2} chipColor={COLORS.accent2}>
          <Panel>
            <Line k="now" v="$6.00" good />
            <Line k="Jan 1" v="$12.00" bad />
          </Panel>
        </ToolCard>
      </FadeOut>
      <FadeOut at={B4}>
        <ToolCard name="Text input" tagline="Also doubles." chip="$0.50 to $1" at={B3 - 2} chipColor={COLORS.accent2}>
          <Panel>
            <Line k="now" v="$0.50" good />
            <Line k="Jan 1" v="$1.00" bad />
          </Panel>
        </ToolCard>
      </FadeOut>
      <FadeOut at={B5}>
        <ToolCard name="Free tier" tagline="Both models." chip="FREE" at={B4 - 2}>
          <Panel>
            <Line k="Flash TTS" v="free tier" good />
            <Line k="Flash-Lite TTS" v="free tier" good />
          </Panel>
        </ToolCard>
      </FadeOut>
      <FadeOut at={B6}>
        <ToolCard name="Batch audio out" tagline="Half price, still doubles." chip="$4.50 to $9" at={B5 - 2} chipColor={COLORS.accent2}>
          <Panel>
            <Line k="now" v="$4.50" good />
            <Line k="Jan 1" v="$9.00" bad />
          </Panel>
        </ToolCard>
      </FadeOut>
      <FadeOut at={CTA}>
        <ToolCard name="The cheap window" tagline="Ends Dec 31." chip="DEC 31" at={B6 - 2} chipColor={COLORS.danger}>
          <Panel>
            <Line k="through Dec 31" v="$9" good />
            <Line k="from Jan 1" v="$18" bad />
          </Panel>
        </ToolCard>
      </FadeOut>
      <AbsoluteFill style={{ opacity: ctaOp }}>
        <CoverImage src="projects/short-113/cover.png" at={CTA} />
        <HookTitle hold onDark at={CTA} kicker="GEMINI VOICE PRICING" lines={[{ text: "TTS $9 NOW" },{ text: "$18 JAN 1", accent: true }]} />
        <div style={{ position: 'absolute', left: SAFE.side, right: SAFE.side, top: SAFE.top + 520, textAlign: 'center', fontFamily: FONT_BODY, fontWeight: 600, fontSize: 44, color: 'rgba(255,255,255,0.82)' }}>
          Nine now. Eighteen later.
        </div>
      </AbsoluteFill>
      <CaptionTrack words={WORDS} />
      <Watermark at={12} />
      <ProgressBar />
    </AbsoluteFill>
  );
};
export default Short113;
